1	// The constructor keeps a public named param (`recorder`) distinct from
2	// the private field it initializes, matching
3	// `vault_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:io';
6	
7	import 'package:path_provider/path_provider.dart';
8	// Aliased — `record`'s own `AudioRecorder` would otherwise clash with
9	// nothing in this file today, but the alias keeps every reference to the
10	// package explicit, per Code Map.
11	import 'package:record/record.dart' as record_pkg;
12	
13	import '../../domain/services/mic_recorder.dart';
14	
15	/// Wraps `package:record`'s `AudioRecorder` behind the [MicRecorder] port.
16	/// A `get_it` singleton (Code Map/`capture_injection.dart`) — one real
17	/// recorder for the app's lifetime, reused across every Insertion Modal
18	/// open, never recreated per "+" tap the way `AudioEntryCubit` itself is.
19	class RecordMicRecorder implements MicRecorder {
20	  RecordMicRecorder({required record_pkg.AudioRecorder recorder})
21	    : _recorder = recorder;
22	
23	  final record_pkg.AudioRecorder _recorder;
24	
25	  /// Set by [start], cleared by [stop]/[cancel] — [stop] has no other way
26	  /// to learn how long the session ran, since `AudioRecorder.stop()` only
27	  /// ever returns the output path.
28	  DateTime? _startedAt;
29	
30	  /// Set by [start], cleared by [stop]/[cancel] — tracked independently
31	  /// of `_recorder`'s own "delete on cancel" contract (Review finding:
32	  /// that contract was asserted in this class's own doc comment but
33	  /// never independently verified) so [cancel] can delete the file
34	  /// itself rather than relying solely on the plugin's behavior.
35	  String? _currentPath;
36	
37	  @override
38	  Future<bool> hasPermission() => _recorder.hasPermission();
39	
40	  @override
41	  Future<void> start() async {
42	    final dir = await getTemporaryDirectory();
43	    final path =
44	        '${dir.path}/cerne_audio_entry_'
45	        '${DateTime.now().microsecondsSinceEpoch}.wav';
46	    await _recorder.start(
47	      // 16kHz mono matches `whisper_ggml`'s own expected input exactly
48	      // (its internal ffmpeg conversion step — `WhisperAudioConvert` —
49	      // falls back to passing the file through unconverted when ffmpeg
50	      // is unavailable, which only works if it's already in this shape).
51	      const record_pkg.RecordConfig(
52	        encoder: record_pkg.AudioEncoder.wav,
53	        sampleRate: 16000,
54	        numChannels: 1,
55	      ),
56	      path: path,
57	    );
58	    _startedAt = DateTime.now();
59	    _currentPath = path;
60	  }
61	
62	  @override
63	  Future<MicRecording?> stop() async {
64	    final path = await _recorder.stop();
65	    final startedAt = _startedAt;
66	    _startedAt = null;
67	    _currentPath = null;
68	    if (path == null || startedAt == null) {
69	      return null;
70	    }
71	    // Review finding: a backward system-clock adjustment mid-recording
72	    // (DST/NTP correction) could otherwise make this negative, which the
73	    // backend's `mediaDurationSeconds: minimum 0` contract rejects —
74	    // floored at 0 rather than trusting the wall clock never moves back.
75	    final elapsed = DateTime.now().difference(startedAt).inSeconds;
76	    return MicRecording(
77	      path: path,
78	      durationSeconds: elapsed < 0 ? 0 : elapsed,
79	    );
80	  }
81	
82	  @override
83	  Future<void> cancel() async {
84	    _startedAt = null;
85	    final path = _currentPath;
86	    _currentPath = null;
87	    await _recorder.cancel();
88	    // Review finding: don't rely solely on the plugin's own "cancel
89	    // deletes the file" contract — delete it ourselves too, best-effort,
90	    // so this class's own doc comment stays true regardless of the
91	    // underlying plugin's actual behavior.
92	    if (path != null) {
93	      try {
94	        await File(path).delete();
95	      } catch (_) {
96	        // Best-effort — the plugin may have already deleted it itself,
97	        // or it may never have existed (e.g. a very early cancel).
98	      }
99	    }
100	  }
101	
102	  @override
103	  Stream<double> get amplitudeStream => _recorder
104	      .onAmplitudeChanged(const Duration(milliseconds: 200))
105	      .map(_normalize);
106	
107	  /// `record`'s own `Amplitude.current` is dBFS, roughly -45 (near
108	  /// silence, in practice — the package's own floor is -160 but normal
109	  /// mic noise never gets that quiet) to 0 (loudest) — rescaled to a
110	  /// 0.0–1.0 range the waveform widget can use directly, with no
111	  /// `package:record` type ever crossing the [MicRecorder] boundary.
112	  double _normalize(record_pkg.Amplitude amplitude) {
113	    const floorDb = -45.0;
114	    final clamped = amplitude.current.clamp(floorDb, 0.0);
115	    return (clamped - floorDb) / -floorDb;
116	  }
117	}
