        ),
      );

      final result = await repository.recognizeText(
        imageBytes: imageBytes,
        mimeType: 'image/jpeg',
      );

      expect(result.isLeft(), isTrue);
      result.match(
        (failure) => expect(failure, isA<OcrNoText>()),
        (_) => fail('expected Left'),
      );
    },
  );
}

