9	import 'data/repositories/media_repository_impl.dart';
10	import 'data/services/image_picker_photo_picker.dart';
11	import 'data/services/record_mic_recorder.dart';
12	import 'data/services/whisper_audio_transcriber.dart';
13	import 'domain/repositories/media_repository.dart';
14	import 'domain/services/audio_transcriber.dart';
15	import 'domain/services/mic_recorder.dart';
16	import 'domain/services/photo_picker.dart';
17	import 'presentation/cubit/audio_entry_cubit.dart';
18	import 'presentation/cubit/photo_entry_cubit.dart';
19	import 'presentation/cubit/text_entry_cubit.dart';
20	
21	/// Registers the `capture` feature into the project's single `get_it`
22	/// instance (`sl`). Unlike every other feature's cubit in this codebase
23	/// (`AccountSettingsCubit`/`AuthCubit`, lazy singletons), [TextEntryCubit]/
24	/// [AudioEntryCubit] are both **factories** — the Insertion Modal needs a
25	/// fresh instance of each per "+" tap (Boundaries: "Modal open resets"),
26	/// not one long-lived instance reused across opens. [MicRecorder]/
27	/// [AudioTranscriber] (and the raw `record`/`whisper_ggml` plugin
28	/// instances underneath them) stay lazy singletons instead — one real
29	/// recorder/transcriber for the app's lifetime, shared across every modal
30	/// open, mirroring `EntriesRepository`'s own registration shape. Called
31	/// from `setupCoreDependencies()` right after `registerEntriesFeature()`
32	/// (Code Map).
33	void registerCaptureFeature() {
34	  sl.registerFactory<TextEntryCubit>(
35	    () => TextEntryCubit(sl<EntriesRepository>()),
36	  );
37	
38	  sl.registerLazySingleton<record_pkg.AudioRecorder>(
39	    record_pkg.AudioRecorder.new,
40	  );
41	  sl.registerLazySingleton<MicRecorder>(
42	    () => RecordMicRecorder(recorder: sl<record_pkg.AudioRecorder>()),
43	  );
44	
45	  sl.registerLazySingleton<WhisperController>(WhisperController.new);
46	  sl.registerLazySingleton<AudioTranscriber>(
47	    () => WhisperAudioTranscriber(controller: sl<WhisperController>()),
48	  );
49	
50	  sl.registerFactory<AudioEntryCubit>(
51	    () => AudioEntryCubit(
52	      sl<MicRecorder>(),
53	      sl<AudioTranscriber>(),
54	      sl<EntriesRepository>(),
55	    ),
56	  );
57	
58	  sl.registerLazySingleton<image_picker_pkg.ImagePicker>(
59	    image_picker_pkg.ImagePicker.new,
60	  );
61	  sl.registerLazySingleton<PhotoPicker>(
62	    () => ImagePickerPhotoPicker(picker: sl<image_picker_pkg.ImagePicker>()),
63	  );
64	
65	  sl.registerLazySingleton<MediaRemoteDataSource>(
66	    () => MediaRemoteDataSource(sl<ApiClient>()),
67	  );
68	  sl.registerLazySingleton<MediaRepository>(
69	    () => MediaRepositoryImpl(remoteDataSource: sl<MediaRemoteDataSource>()),
70	  );
71	
72	  sl.registerFactory<PhotoEntryCubit>(
73	    () => PhotoEntryCubit(
74	      sl<PhotoPicker>(),
75	      sl<MediaRepository>(),
76	      sl<EntriesRepository>(),
77	    ),
78	  );
79	}
