1	import 'dart:io';
2	import 'dart:typed_data';
3	
4	import 'package:flutter_bloc/flutter_bloc.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../../entries/domain/entities/entry.dart';
8	import '../../../entries/domain/repositories/entries_repository.dart';
9	import '../../domain/repositories/media_repository.dart';
10	import '../../domain/services/photo_picker.dart';
11	
12	/// `PhotoEntryCubit`'s own sealed state hierarchy — separate from
13	/// `TextEntryState`/`AudioCaptureState` (Boundaries: "own sealed
14	/// `PhotoCaptureState`"). No common base-class field, same rationale as
15	/// `AudioCaptureState`: [PhotoIdle] has nothing in common with
16	/// [PhotoRecognized], for instance.
17	sealed class PhotoCaptureState {
18	  const PhotoCaptureState();
19	}
20	
21	/// The state immediately after the modal opens on the Foto tab, after
22	/// leaving mid-pick/mid-OCR (Never: this story's trivial cross-tab
23	/// case), and the state a fresh `PhotoEntryCubit` always starts in.
24	/// `InsertionModal`'s own `_FotoTab` renders the Câmera/Galeria capture
25	/// buttons for this state.
26	class PhotoIdle extends PhotoCaptureState {
27	  const PhotoIdle();
28	}
29	
30	/// A photo was picked, `MediaRepository.recognizeText()` in flight —
31	/// `_FotoTab` shows a thumbnail + "Reconhecendo texto..." for the whole
32	/// duration of this state (Acceptance Criteria). No separate "recording"-
33	/// style intermediate phase (Design Notes): picking is one blocking OS
34	/// call, so [PhotoIdle] goes straight here once the picker returns a file.
35	class PhotoProcessing extends PhotoCaptureState {
36	  const PhotoProcessing({required this.path, required this.mimeType});
37	
38	  final String path;
39	  final String mimeType;
40	}
41	
42	/// OCR succeeded with usable text — [text] is editable before Salvar
43	/// (Acceptance Criteria), mirrored by [PhotoEntryCubit.updateText].
44	/// [saving] folds `TextEntrySaving`'s role into this same state, same
45	/// convention as `AudioTranscribed.saving`.
46	class PhotoRecognized extends PhotoCaptureState {
47	  const PhotoRecognized({
48	    required this.path,
49	    required this.mimeType,
50	    required this.text,
51	    required this.saving,
52	  });
53	
54	  final String path;
55	  final String mimeType;
56	  final String text;
57	  final bool saving;
58	
59	  PhotoRecognized copyWith({String? text, bool? saving}) => PhotoRecognized(
60	    path: path,
61	    mimeType: mimeType,
62	    text: text ?? this.text,
63	    saving: saving ?? this.saving,
64	  );
65	}
66	
67	/// A save attempt succeeded — `InsertionModal`'s listener reacts to this
68	/// exactly like `TextEntrySaved`/`AudioSaved` (announce, then pop).
69	/// Terminal, same rationale as those two states' own docs.
70	class PhotoSaved extends PhotoCaptureState {
71	  const PhotoSaved();
72	}
73	
74	/// The 3-way discriminator driving `_FotoTab`'s three distinct error
75	/// branches (Design Notes: "a discriminator is clearer than overloading
76	/// nullability tricks" — unlike `AudioError`'s binary `canRetry`, Photo
77	/// has two distinct non-retryable backend codes needing different UI).
78	enum PhotoErrorKind {
79	  /// `Failure.ocrNoText` — "Tentar novamente" (re-OCRs the same image)
80	  /// and "Salvar só a foto" (saves a fixed placeholder) are both offered.
81	  ocrNoText,
82	
83	  /// `Failure.payloadTooLarge` — no retry, no save-without-text; the only
84	  /// way forward is picking a different photo.
85	  payloadTooLarge,
86	
87	  /// Any other `Failure` — a generic OCR-call failure ([text] `null`,
88	  /// "Tentar novamente" re-OCRs) or a save failure ([text] non-null,
89	  /// re-running the failed call means tapping Salvar again, same shape
90	  /// as `AudioError`).
91	  generic,
92	}
93	
94	/// The last attempt failed — covers every failure row of the I/O matrix:
95	/// `OCR_NO_TEXT`, `PAYLOAD_TOO_LARGE`, a generic OCR-call failure, or a
96	/// save failure (non-null [text]).
97	class PhotoError extends PhotoCaptureState {
98	  const PhotoError({
99	    required this.path,
100	    required this.mimeType,
101	    required this.message,
102	    required this.kind,
103	    this.text,
104	  });
105	
106	  final String path;
107	  final String mimeType;
108	  final String message;
109	  final PhotoErrorKind kind;
110	
111	  /// Non-null only for a save failure ([PhotoErrorKind.generic]) — lets
112	  /// `_FotoTab` keep rendering the editable text field under the inline
113	  /// error, same as `AudioError.text`/`TextEntryError`'s own rendering.
114	  final String? text;
115	}
116	
117	/// Drives the Foto tab's pick -> processingOcr -> recognized/error
118	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
119	/// tap, same convention as `TextEntryCubit`/`AudioEntryCubit` —
120	/// [PhotoPicker]/[MediaRepository] themselves stay long-lived `get_it`
121	/// singletons (`capture_injection.dart`).
122	class PhotoEntryCubit extends Cubit<PhotoCaptureState> {
123	  PhotoEntryCubit(
124	    this._photoPicker,
125	    this._mediaRepository,
126	    this._entriesRepository,
127	  ) : super(const PhotoIdle());
128	
129	  final PhotoPicker _photoPicker;
130	  final MediaRepository _mediaRepository;
131	  final EntriesRepository _entriesRepository;
132	
133	  static const _noTextPlaceholder =
134	      'Registro fotográfico (sem texto reconhecido)';
135	
136	  /// Bumped by [cancel] (and by every pick/retry attempt) so an in-flight
137	  /// picker/OCR continuation can tell "the user already left the Foto tab"
138	  /// apart from "nothing has changed since I started" — same role
139	  /// `AudioEntryCubit._generation` plays for the picker call and the OCR
140	  /// network call here (Boundaries).
141	  int _generation = 0;
142	
143	  /// Guards against a second overlapping picker call (e.g. a fast
144	  /// double-tap on Câmera before the UI rebuilds past [PhotoIdle]).
145	  bool _picking = false;
146	
147	  Future<void> pickFromCamera() => _pick(_photoPicker.pickFromCamera);
148	
149	  Future<void> pickFromGallery() => _pick(_photoPicker.pickFromGallery);
150	
151	  Future<void> _pick(Future<PickedPhoto?> Function() pick) async {
152	    final current = state;
153	    final canPick =
154	        !_picking &&
155	        (current is PhotoIdle ||
156	            (current is PhotoError &&
157	                current.kind == PhotoErrorKind.payloadTooLarge));
158	    if (!canPick) {
159	      return;
160	    }
161	    _picking = true;
162	    final generation = ++_generation;
163	    PickedPhoto? photo;
164	    try {
165	      photo = await pick();
166	    } catch (_) {
167	      // A thrown PlatformException (native-side error) must never escape
168	      // uncaught — treated the same as a plain user cancel, since this
169	      // story offers no dedicated "picker failed" UI (not in the I/O
170	      // matrix).
171	      _picking = false;
172	      if (isClosed || generation != _generation) {
173	        return;
174	      }
175	      emit(const PhotoIdle());
176	      return;
177	    }
178	    _picking = false;
179	    if (isClosed || generation != _generation) {
180	      return;
181	    }
182	    if (photo == null) {
183	      // I/O matrix: "User cancels picker" -> stays on PhotoIdle's capture
184	      // buttons. If the re-pick was attempted from a `payloadTooLarge`
185	      // error, drop that stale error too rather than leaving it on
186	      // screen with nothing that produced it anymore.
187	      if (current is PhotoError) {
188	        emit(const PhotoIdle());
189	      }
190	      return;
191	    }
192	    emit(PhotoProcessing(path: photo.path, mimeType: photo.mimeType));
193	    await _recognize(photo.path, photo.mimeType, generation);
194	  }
195	
196	  Future<void> _recognize(
197	    String path,
198	    String mimeType,
199	    int generation,
200	  ) async {
201	    Uint8List bytes;
202	    try {
203	      bytes = await File(path).readAsBytes();
204	    } catch (_) {
205	      if (isClosed || generation != _generation) {
206	        return;
207	      }
208	      emit(
209	        PhotoError(
210	          path: path,
211	          mimeType: mimeType,
212	          message: 'Não foi possível ler a foto selecionada.',
213	          kind: PhotoErrorKind.generic,
214	        ),
215	      );
216	      return;
217	    }
218	    final result = await _mediaRepository.recognizeText(
219	      imageBytes: bytes,
220	      mimeType: mimeType,
221	    );
222	    // Guards a tab switch away mid-OCR (`cancel()`, below) that already
223	    // reset the state by the time this resolves — without this, a stale
224	    // OCR result would still land and resurrect a flow the user left.
225	    if (isClosed || generation != _generation) {
226	      return;
227	    }
228	    result.match(
229	      (failure) => emit(
230	        PhotoError(
231	          path: path,
232	          mimeType: mimeType,
233	          message: failure.message,
234	          kind: switch (failure) {
235	            OcrNoText() => PhotoErrorKind.ocrNoText,
236	            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
237	            _ => PhotoErrorKind.generic,
