382	  /// Called when the Foto tab loses focus mid-pick/mid-OCR
383	  /// (`InsertionModal`'s tab-switch listener) — I/O matrix's "Leave tab
384	  /// mid-pick/OCR" row: the in-flight picker/OCR call is discarded, no
385	  /// `create()` ever fires. A no-op for every other state when
386	  /// [discardPreserved] is `false` (the default) — in particular
387	  /// [PhotoRecognized]/[PhotoError], where the Never clause's trivial
388	  /// scope (resource safety only, not full Story 3.4 cancel-safety)
389	  /// means a tab switch must preserve the result rather than discard it
390	  /// — mirrors `AudioEntryCubit.cancel()`'s own `discardPreserved`
391	  /// convention exactly.
392	  ///
393	  /// [discardPreserved] — `InsertionModal.show()`'s `finally` also calls
394	  /// this (before `close()`) when the *whole modal* is dismissed (✕/
395	  /// swipe-down/barrier tap), not just the tab. In that case there's no
396	  /// "switch back to the tab later" to preserve for — the cubit is about
397	  /// to be closed — so a preserved [PhotoRecognized]/[PhotoError]'s
398	  /// picked-photo temp file would otherwise never be cleaned up and leak
399	  /// on disk forever (Review finding — the comment this replaced
400	  /// incorrectly claimed Foto "never creates a temp file of its own";
401	  /// `image_picker` does, every pick). Pass `true` only from that call
402	  /// site.
403	  Future<void> cancel({bool discardPreserved = false}) async {
404	    // Bumped unconditionally — including when the state below doesn't
405	    // match — so an in-flight `_pick`/`_recognize`/`retry` continuation
406	    // still sees the mismatch and aborts itself even while still awaiting
407	    // (Review-finding rationale mirrored from `AudioEntryCubit.cancel()`).
408	    _generation++;
409	    // Review finding: without this, leaving the Foto tab while the
410	    // native picker call itself (not yet `PhotoProcessing`) was still in
411	    // flight left `_picking` stuck `true` forever — the `_generation`
412	    // bump above already makes that stale continuation a no-op, so
413	    // resetting this eagerly is always safe.
414	    _picking = false;
415	    final current = state;
416	    if (current is PhotoProcessing) {
417	      unawaited(_deletePickedFile(current.path));
418	      emit(const PhotoIdle());
419	    } else if (discardPreserved) {
420	      final path = switch (current) {
421	        PhotoRecognized(path: final p) => p,
422	        PhotoError(path: final p) => p,
423	        _ => null,
424	      };
425	      if (path != null) {
426	        unawaited(_deletePickedFile(path));
427	      }
428	    }
429	  }
